function parseBoard(r){const s=r.content.filter(x=>x.type==="text").map(x=>x.text).join("\\n");const b={};for(const line of s.split("\\n")){const m=line.match(/^\\s*([1-9])\\s+([.XO](?:\\s+[.XO]){8})\\s+[1-9]\\s*$/);if(m)m[2].split(/\\s+/).forEach((v,i)=>b[cols[i]+m[1]]=v);}return {s,b};}
