async function play(move,note){let r=await tools.mcp__go__play({move});const {s,b}=parseBoard(r);const inv=inspect(b);let log=load("log31");log.responses.push({move,response:r});log.inspections.push(inv);log.notes.push(note);store("log31",log);store("board31",b);await save();text(s);text(inv);}
`;
